import csv
from datetime import datetime
from collections import defaultdict

input_path = '/home/agent/workspace/bookstore_orders.csv'
output_path = '/home/agent/workspace/carrier-delivery-time.csv'

stats = defaultdict(lambda: {'count':0, 'total_hours':0.0})

def parse_dt(s):
    if not s:
        return None
    try:
        # handle formats with time or date only
        for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d'):
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                continue
        return None
    except Exception:
        return None

with open(input_path, newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['fulfillment_status'].strip().lower() != 'delivered':
            continue
        carrier = row['carrier_name'].strip() or 'Unknown'
        order_ts = parse_dt(row['order_timestamp'].strip())
        actual_dt = parse_dt(row['actual_delivery_date'].strip())
        if not order_ts or not actual_dt:
            continue
        hours = (actual_dt - order_ts).total_seconds() / 3600.0
        if hours < 0:
            continue
        stats[carrier]['count'] += 1
        stats[carrier]['total_hours'] += hours

results = []
for carrier, data in stats.items():
    cnt = data['count']
    if cnt == 0:
        continue
    avg = data['total_hours'] / cnt
    results.append({
        'CarrierName': carrier,
        'DeliveredOrders': cnt,
        'AvgDeliveryHours': round(avg, 2)
    })

results.sort(key=lambda x: x['AvgDeliveryHours'])

with open(output_path, 'w', newline='', encoding='utf-8') as out:
    writer = csv.writer(out)
    writer.writerow(['CarrierName','DeliveredOrders','AvgDeliveryHours'])
    for r in results:
        writer.writerow([r['CarrierName'], r['DeliveredOrders'], f"{r['AvgDeliveryHours']:.2f}"])

print(f"Wrote {output_path}")

