def perft(fen: str, depth: int) -> int:
    if depth == 0:
        return 1
    total = 0
    for mv in legal_moves(fen):
        new_fen = _make_move(fen, mv)
        total += perft(new_fen, depth - 1)
    return total

def _parse_fen_full(fen):
    parts = fen.split()
    board_ranks = parts[0].split('/')
    board = []
    for rank in board_ranks:
        row = []
        for ch in rank:
            if ch.isdigit():
