    halfmove = parts[4] if len(parts) > 4 else '0'
    fullmove = parts[5] if len(parts) > 5 else '1'
    return board, active, castling, en_passant, halfmove, fullmove

def _square_name(r, c):
    return chr(ord('a') + c) + str(8 - r)

def _in_board(r, c):
    return 0 <= r < 8 and 0 <= c < 8

def _square_under_attack(board, tr, tc, attacker_is_white):
    # returns True if square (tr,tc) is attacked by any piece of attacker_is_white
    for r in range(8):
        for c in range(8):
            piece = board[r][c]
            if not piece:
                continue
            is_white = piece.isupper()
            if is_white != attacker_is_white:
                continue
            ptype = piece.upper()
            if ptype == 'P':
                dr = -1 if is_white else 1
                for dc in (-1, 1):
                    nr, nc = r + dr, c + dc
                    if nr == tr and nc == tc:
                        return True
            elif ptype == 'N':
                for dr, dc in ((2,1),(1,2),(-1,2),(-2,1),(-2,-1),(-1,-2),(1,-2),(2,-1)):
                    if r + dr == tr and c + dc == tc:
                        return True
            elif ptype == 'K':
                if max(abs(r - tr), abs(c - tc)) == 1:
                    return True
            elif ptype in ('B', 'R', 'Q'):
                dirs = []
                if ptype in ('B', 'Q'):
                    dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
                if ptype in ('R', 'Q'):
                    dirs += [(-1,0),(1,0),(0,-1),(0,1)]
                for dr, dc in dirs:
                    nr, nc = r + dr, c + dc
                    while _in_board(nr, nc):
                        if nr == tr and nc == tc:
                            return True
                        if board[nr][nc]:
                            break
                        nr += dr
                        nc += dc
    return False

def _add_sliding_moves(board, r, c, dirs, moves, white):
    enemy = lambda p: (p and p.islower()) if white else (p and p.isupper())
    for dr, dc in dirs:
        nr, nc = r + dr, c + dc
        while _in_board(nr, nc):
            target = board[nr][nc]
            if not target:
                moves.append(f"{_square_name(r,c)}{_square_name(nr,nc)}")
            elif enemy(target):
                moves.append(f"{_square_name(r,c)}{_square_name(nr,nc)}")
                break
            else:
                break
            nr += dr
            nc += dc

