                            moves.append(f"{_square_name(r,c)}{_square_name(r2,c)}")
                for dc in (-1, 1):
                    c1 = c + dc
                    if _in_board(r1, c1) and enemy(board[r1][c1]):
                        moves.append(f"{_square_name(r,c)}{_square_name(r1,c1)}")
            elif ptype == 'N':
